WITH base AS (SELECT id, product_name, category, brand, stock_qty, launch_date, tags, supplier_id, ARRAY_JOIN(tags, '|') tags_text, cost * price margin FROM products WHERE launch_date >= DATE '2023-04-16' AND supplier_id = 25), metrics AS (SELECT *, COUNT(stock_qty) OVER (PARTITION BY supplier_id) supplier_id_count_stock_qty, SUM(margin) OVER (PARTITION BY brand) brand_sum_margin FROM base), with_dims AS (SELECT s.id, s.product_name, s.category, s.brand, s.stock_qty, s.supplier_id, s.supplier_id_count_stock_qty, s.brand_sum_margin, b.rating, b.supplier_name, b.city FROM metrics s JOIN suppliers b ON s.supplier_id = b.id), cleaned AS (SELECT id, category, brand, supplier_id, supplier_id_count_stock_qty, rating, supplier_name, city, stock_qty + supplier_id_count_stock_qty stock_qty_plus_supplier_id_count_stock_qty, COALESCE(brand, 'Unknown') brand_filled, COALESCE(brand, 'NONE') resolved_brand FROM with_dims WHERE supplier_id_count_stock_qty > 7), with_last AS (SELECT s.id, s.category, s.brand, s.rating, s.supplier_name, s.brand_filled, s.resolved_brand, latest.sale_date FROM cleaned s LEFT JOIN LATERAL (SELECT c.sale_date FROM store_sales c WHERE c.product_id = s.id ORDER BY c.units DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT category, AVG(rating) FILTER (WHERE brand = 'Stark') AS stark_avg_rating, SUM(rating) AS total_rating FROM with_last GROUP BY category
